reactiveclass Ping(5) {
	knownrebecs { 
		Pong pong;
	}
	statevars {
		int count;
	}

	Ping() {
		count = 0;
		self.initial();
	}

	msgsrv initial() {
		// Ping started the game!
		pong.pingMessage();
	}

	msgsrv pongMessage() {
		count = count + 1;
		// Ping received pong #count from sender
		if (count >= 10) {
			((Pong)sender).stopMessage();
			// Ping stopped
		} else {
			((Pong)sender).pingMessage();
		}
	}
}

